import { ExceptionFilter, Catch, ArgumentsHost, HttpException, HttpStatus, Logger } from '@nestjs/common';
import { FastifyReply } from 'fastify';

@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(GlobalExceptionFilter.name);

  catch(exception: unknown, host: ArgumentsHost): void {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<FastifyReply>();

    const status = exception instanceof HttpException
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;

    let errorCode = 'INTERNAL_SERVER_ERROR';
    let message = 'Internal server error';
    let details: any = undefined;

    if (exception instanceof HttpException) {
      const resp = exception.getResponse();
      if (typeof resp === 'string') {
        message = resp;
      } else if (typeof resp === 'object' && resp !== null) {
        message = (resp as any).message || message;
        errorCode = (resp as any).code || (resp as any).error || errorCode;
        details = (resp as any).details;
      }
    } else {
      message = exception instanceof Error ? exception.message : String(exception);
    }

    const body = {
      error: {
        code: errorCode,
        message,
        statusCode: status,
        details,
        timestamp: new Date().toISOString(),
      },
    };

    if (status >= 500) {
      this.logger.error(`[${status}] ${message}`, exception instanceof Error ? exception.stack : undefined);
    }

    response.status(status).send(body);
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface Response<T> {
  success: boolean;
  data: T;
  timestamp: string;
}

@Injectable()
export class TransformInterceptor<T>
  implements NestInterceptor<T, Response<T>>
{
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<Response<T>> {
    return next.handle().pipe(
      map((data) => {
        // If data is already in the normalized Response structure, add timestamp and return
        if (data && typeof data === 'object' && 'success' in data && 'data' in data && Object.keys(data).length <= 3) {
          return {
            ...data,
            timestamp: data.timestamp || new Date().toISOString(),
          };
        }

        // Unwrap { data: ... } if controllers still return it
        const actualData = data && typeof data === 'object' && 'data' in data && Object.keys(data).length === 1 ? data.data : data;

        return {
          success: true,
          data: actualData,
          timestamp: new Date().toISOString(),
        };
      }),
    );
  }
}

import { BadRequestException } from '@nestjs/common';
import { ZodError } from 'zod';

import type { PipeTransform, ArgumentMetadata} from '@nestjs/common';
import type { ZodSchema} from 'zod';


export class ZodValidationPipe implements PipeTransform {
  constructor(private schema: ZodSchema) {}

  transform(value: unknown, metadata: ArgumentMetadata) {
    if (metadata.type !== 'body') {
      return value;
    }

    try {
      const parsedValue = this.schema.parse(value);
      return parsedValue;
    } catch (error) {
      if (error instanceof ZodError) {
        throw new BadRequestException({
          code: 'VALIDATION_ERROR',
          message: 'Validation failed',
          details: error.errors,
        });
      }
      throw new BadRequestException('Validation failed');
    }
  }
}

